item.debug_logs = {};

function forceParse(value, fieldName) {
    if (typeof value !== 'string') return value;

    // 💥 СРЕЗАЕМ ЗНАК '=' В НАЧАЛЕ СТРОКИ (Если n8n его туда приклеил)
    let cleanValue = value.trim();
