        item.debug_logs[fieldName + '_error_1'] = e1.message;
        try {
            // Попытка 2: Бульдозер
            let bulldozerParsed = Function('"use strict";return (' + cleanValue + ')')();
            item.debug_logs[fieldName + '_status'] = "Успешно (Бульдозер)";
            return bulldozerParsed;
        } catch (e2) {
            item.debug_logs[fieldName + '_error_2'] = e2.message;
